def plan_task(project_id, task_id=None, name=None, description=None, notes=None, priority=None, related_files=None, create_task=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(alphabet[random.randint(0, len(alphabet) - 1)] for _ in range(20))

    def _log(endpoint, status, latency_ms, project_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("cot_rql_"),
            "endpoint": endpoint,
            "project_id": project_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "plan_task"

    try:
        if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
            _log(endpoint, "error", (time.time() - t0) * 1000, project_id=None, detail="bad_project_id")
            return _err("VALIDATION_ERROR", "project_id is required and must match ^cot_prj_[0-9A-Z]{18,}$")

        if task_id is not None and (not isinstance(task_id, str) or not re.match(r"^cot_tsk_[0-9A-Z]{18,}$", task_id)):
            _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="bad_task_id")
            return _err("VALIDATION_ERROR", "task_id must match ^cot_tsk_[0-9A-Z]{18,}$")

        if create_task is not None and not isinstance(create_task, bool):
            _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="bad_create_task")
            return _err("VALIDATION_ERROR", "create_task must be boolean when provided")

        if notes is not None and not isinstance(notes, str):
            _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="bad_notes")
            return _err("VALIDATION_ERROR", "notes must be a string when provided")

        if priority is not None and not isinstance(priority, int):
            _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="bad_priority")
            return _err("VALIDATION_ERROR", "priority must be an integer when provided")

        if related_files is not None:
            if not isinstance(related_files, list) or any(not isinstance(x, str) for x in related_files):
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="bad_related_files")
                return _err("VALIDATION_ERROR", "related_files must be an array of strings when provided")
            if len(related_files) > 200:
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="related_files_limit")
                return _err("VALIDATION_ERROR", "related_files length must be <= 200")

        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []

        project = next((p for p in projects if p.get("id") == project_id), None)
        if project is None:
            # Create if missing (business rule)
            now = _now()
            project = {
                "id": project_id,
                "name": project_id,
                "repository_url": None,
                "rules_spec": None,
                "rules_version": 0,
                "rules_updated_at": None,
                "status": "active",
                "created_at": now,
                "updated_at": now,
            }
            projects.append(project)
            _save("projects.json", projects)

        tasks = _load("tasks.json")
        if not isinstance(tasks, list):
            tasks = []

        def _active_tasks_for_project():
            return [t for t in tasks if t.get("project_id") == project_id and t.get("deleted_at") is None]

        assoc_task = None
        mutated_task = None

        if task_id is not None:
            assoc_task = next((t for t in tasks if t.get("id") == task_id and t.get("project_id") == project_id and t.get("deleted_at") is None), None)
            if assoc_task is None:
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="task_not_found")
                return _err("NOT_FOUND", "Task not found for project_id/task_id")
        else:
            if create_task is not True:
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="missing_task_or_create")
                return _err("VALIDATION_ERROR", "task_id omitted; create_task must be true to create a new task")
            if not isinstance(name, str) or name.strip() == "":
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="missing_name")
                return _err("VALIDATION_ERROR", "name is required when creating a task")
            if description is not None and not isinstance(description, str):
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="bad_description")
                return _err("VALIDATION_ERROR", "description must be a string when provided")

            # enforce project tasks quota (<= 500 non-deleted)
            if len(_active_tasks_for_project()) >= 500:
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="tasks_quota")
                return _err("QUOTA_EXCEEDED", "Project task limit exceeded (max 500 non-deleted tasks)")

            # uniqueness: (project_id, name) where deleted_at is null
            existing_same = next((t for t in tasks if t.get("project_id") == project_id and t.get("deleted_at") is None and t.get("name") == name), None)
            if existing_same is not None:
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="name_conflict")
                return _err("CONFLICT", "A non-deleted task with the same name already exists in this project")

            # priority between 1 and 5 (schema). Tool says "higher means more important" but schema uses 1..5.
            pr = priority if priority is not None else 3
            if not isinstance(pr, int) or pr < 1 or pr > 5:
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="priority_range")
                return _err("VALIDATION_ERROR", "priority must be between 1 and 5")

            now = _now()
            assoc_task = {
                "id": _gen_id("cot_tsk_"),
                "project_id": project_id,
                "name": name,
                "description": description,
                "notes": notes,
                "priority": pr,
                "status": "planned",
                "implementation_guide": None,
                "verification_criteria": None,
                "related_files": related_files if related_files is not None else [],
                "summary": None,
                "completion_report": None,
                "completed_at": None,
                "deleted_at": None,
                "created_at": now,
                "updated_at": now,
            }
            tasks.append(assoc_task)
            _save("tasks.json", tasks)
            mutated_task = assoc_task

        # Create thought session for plan_task and close it with a summary (business rule)
        sessions = _load("thought_sessions.json")
        if not isinstance(sessions, list):
            sessions = []

        now = _now()
        summary_parts = []
        summary_parts.append(f"Planning session created for task '{assoc_task.get('name')}' ({assoc_task.get('id')}).")
        if notes:
            summary_parts.append("Notes provided for planning context.")
        if related_files:
            summary_parts.append(f"Related files provided: {len(related_files)}.")
        summary_parts.append("Session closed after planning initialization.")
        summary = " ".join(summary_parts)

        sess = {
            "id": _gen_id("cot_ths_"),
            "project_id": project_id,
            "root_task_id": assoc_task.get("id"),
            "mode": "plan_task",
            "status": "closed",
            "summary": summary,
            "next_thought_needed": False,
            "created_at": now,
            "updated_at": now,
            "closed_at": now,
        }
        sessions.append(sess)
        _save("thought_sessions.json", sessions)

        # update project updated_at (and leave status/rules untouched)
        project["updated_at"] = _now()
        _save("projects.json", projects)

        resp = {
            "thought_session": sess,
            "task": assoc_task,
        }
        if mutated_task is None:
            resp["task_updated"] = False
        else:
            resp["task_updated"] = True

        _log(endpoint, "ok", (time.time() - t0) * 1000, project_id=project_id)
        return resp
    except Exception as e:
        _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id if isinstance(project_id, str) else None, detail="exception")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def analyze_task(project_id, task_id, session_id=None, include_codebase_check=None, related_files=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(alphabet[random.randint(0, len(alphabet) - 1)] for _ in range(20))

    def _log(endpoint, status, latency_ms, project_id=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("cot_rql_"),
            "endpoint": endpoint,
            "project_id": project_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()
    endpoint = "analyze_task"

    try:
        if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
            _log(endpoint, "error", (time.time() - t0) * 1000, detail="bad_project_id")
            return _err("VALIDATION_ERROR", "project_id must match ^cot_prj_[0-9A-Z]{18,}$")
        if not isinstance(task_id, str) or not re.match(r"^cot_tsk_[0-9A-Z]{18,}$", task_id):
            _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="bad_task_id")
            return _err("VALIDATION_ERROR", "task_id must match ^cot_tsk_[0-9A-Z]{18,}$")
        if session_id is not None and (not isinstance(session_id, str) or not re.match(r"^cot_ths_[0-9A-Z]{18,}$", session_id)):
            _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="bad_session_id")
            return _err("VALIDATION_ERROR", "session_id must match ^cot_ths_[0-9A-Z]{18,}$")
        if include_codebase_check is not None and not isinstance(include_codebase_check, bool):
            _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="bad_include_codebase_check")
            return _err("VALIDATION_ERROR", "include_codebase_check must be boolean when provided")
        if related_files is not None:
            if not isinstance(related_files, list) or any(not isinstance(x, str) for x in related_files):
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="bad_related_files")
                return _err("VALIDATION_ERROR", "related_files must be an array of strings when provided")
            if len(related_files) > 200:
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="related_files_limit")
                return _err("VALIDATION_ERROR", "related_files length must be <= 200")

        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        project = next((p for p in projects if p.get("id") == project_id), None)
        if project is None:
            _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="project_not_found")
            return _err("NOT_FOUND", "Project not found")

        tasks = _load("tasks.json")
        if not isinstance(tasks, list):
            tasks = []
        task = next((t for t in tasks if t.get("id") == task_id and t.get("project_id") == project_id and t.get("deleted_at") is None), None)
        if task is None:
            _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="task_not_found")
            return _err("NOT_FOUND", "Task not found")

        sessions = _load("thought_sessions.json")
        if not isinstance(sessions, list):
            sessions = []

        sess = None
        now = _now()
        if session_id is None:
            sess = {
                "id": _gen_id("cot_ths_"),
                "project_id": project_id,
                "root_task_id": task_id,
                "mode": "analyze_task",
                "status": "closed",
                "summary": None,
                "next_thought_needed": False,
                "created_at": now,
                "updated_at": now,
                "closed_at": now,
            }
            sessions.append(sess)
        else:
            sess = next((s for s in sessions if s.get("id") == session_id), None)
            if sess is None:
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="session_not_found")
                return _err("NOT_FOUND", "Thought session not found")
            if sess.get("project_id") != project_id:
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="session_project_mismatch")
                return _err("CONFLICT", "Thought session does not belong to project_id")
            if sess.get("root_task_id") not in (None, task_id):
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="session_task_mismatch")
                return _err("CONFLICT", "Thought session does not belong to task_id")
            if sess.get("status") != "open":
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="session_not_open")
                return _err("INVALID_TRANSITION", "Cannot append analysis to a non-open session")
            if sess.get("mode") not in ("analyze_task",):
                _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id, detail="session_mode_mismatch")
                return _err("CONFLICT", "session_id mode mismatch (expected analyze_task)")
            sess["updated_at"] = now
            sess["status"] = "closed"
            sess["closed_at"] = now

        # Store only high-level artifacts in summary; do not require mutation.
        parts = [f"Analysis recorded for task '{task.get('name')}' ({task_id})."]
        if include_codebase_check:
            parts.append("Included explicit codebase inspection.")
        if related_files:
            parts.append(f"Focused on {len(related_files)} related files.")
        sess["summary"] = " ".join(parts)

        _save("thought_sessions.json", sessions)

        # Optional allowed mutation: if related_files provided, update task.related_files (within constraints)
        task_updated_fields = {}
        if related_files is not None:
            task["related_files"] = related_files
            task["updated_at"] = _now()
            task_updated_fields["related_files"] = related_files
            _save("tasks.json", tasks)

        project["updated_at"] = _now()
        _save("projects.json", projects)

        _log(endpoint, "ok", (time.time() - t0) * 1000, project_id=project_id)
        return {"thought_session": sess, "task": task, "task_updated_fields": task_updated_fields}
    except Exception as e:
        _log(endpoint, "error", (time.time() - t0) * 1000, project_id=project_id if isinstance(project_id, str) else None, detail="exception")
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

