def split_tasks(project_id, root_task_id, updateMode, max_tasks=None, create_dependencies=None, backup_reason=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "split_tasks"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid_like(n=22):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return "".join(secrets.choice(alphabet) for _ in range(n))

    def _gen_id(prefix):
        return prefix + _ulid_like(22)

    def _log(status, code=None, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("cot_rql_"),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "project_id": project_id if isinstance(project_id, str) else None,
            "root_task_id": root_task_id if isinstance(root_task_id, str) else None,
            "updateMode": updateMode if isinstance(updateMode, str) else None,
        }
        if code or message:
            row["error"] = {"code": code, "message": message}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        # 120/min per project per endpoint
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if r.get("project_id") != project_id:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded (120/min) for this project and endpoint.")
        return None

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
        _log("error", "VALIDATION_ERROR", "Invalid project_id format.")
        return _err("VALIDATION_ERROR", "Invalid project_id format.")
    if not isinstance(root_task_id, str) or not re.match(r"^cot_tsk_[0-9A-Z]{18,}$", root_task_id):
        _log("error", "VALIDATION_ERROR", "Invalid root_task_id format.")
        return _err("VALIDATION_ERROR", "Invalid root_task_id format.")
    if updateMode not in ("append", "overwrite", "selective", "clearAllTasks"):
        _log("error", "VALIDATION_ERROR", "Invalid updateMode.", allowed=["append", "overwrite", "selective", "clearAllTasks"])
        return _err("VALIDATION_ERROR", "Invalid updateMode.", allowed=["append", "overwrite", "selective", "clearAllTasks"])
    if max_tasks is not None and (not isinstance(max_tasks, int) or max_tasks <= 0):
        _log("error", "VALIDATION_ERROR", "max_tasks must be a positive integer when provided.")
        return _err("VALIDATION_ERROR", "max_tasks must be a positive integer when provided.")
    if create_dependencies is not None and not isinstance(create_dependencies, bool):
        _log("error", "VALIDATION_ERROR", "create_dependencies must be a boolean when provided.")
        return _err("VALIDATION_ERROR", "create_dependencies must be a boolean when provided.")
    if backup_reason is not None and backup_reason not in ("clear_all_tasks", "split_tasks_clearAllTasks", "split_tasks_overwrite"):
        _log("error", "VALIDATION_ERROR", "Invalid backup_reason.")
        return _err("VALIDATION_ERROR", "Invalid backup_reason.")

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    deps = _load("task_dependencies.json")
    if not isinstance(deps, list):
        deps = []
    backups = _load("task_backups.json")
    if not isinstance(backups, list):
        backups = []

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj:
        _log("error", "NOT_FOUND", "Project not found.")
        return _err("NOT_FOUND", "Project not found.")
    if prj.get("status") not in ("active", "archived"):
        _log("error", "VALIDATION_ERROR", "Project has invalid status.")
        return _err("VALIDATION_ERROR", "Project has invalid status.")
    if prj.get("status") == "archived":
        _log("error", "INVALID_TRANSITION", "Cannot split tasks in an archived project.")
        return _err("INVALID_TRANSITION", "Cannot split tasks in an archived project.")

    # Root task must exist and be non-deleted, but DOES NOT have to be in same project in real usage
    # (audit shows cross-project root_task_id is used). We still require it exists and is not deleted.
    root_task = next((t for t in tasks if isinstance(t, dict) and t.get("id") == root_task_id and t.get("deleted_at") is None), None)
    if not root_task:
        _log("error", "NOT_FOUND", "Root task not found or is deleted.")
        return _err("NOT_FOUND", "Root task not found or is deleted.")

    # Determine whether we need a backup/clear step
    need_backup = updateMode in ("overwrite", "clearAllTasks")
    if need_backup:
        if backup_reason is None:
            backup_reason = "split_tasks_overwrite" if updateMode == "overwrite" else "split_tasks_clearAllTasks"
        expected = "split_tasks_overwrite" if updateMode == "overwrite" else "split_tasks_clearAllTasks"
        if backup_reason != expected:
            _log("error", "VALIDATION_ERROR", f"backup_reason must be '{expected}' when updateMode='{updateMode}'.")
            return _err("VALIDATION_ERROR", f"backup_reason must be '{expected}' when updateMode='{updateMode}'.")

        # backup quota: at most 20 created backups per project
        created_cnt = 0
        for b in backups:
            if isinstance(b, dict) and b.get("project_id") == project_id and b.get("status") == "created":
                created_cnt += 1
        if created_cnt >= 20:
            _log("error", "QUOTA_EXCEEDED", "Backup quota exceeded: at most 20 created backups per project.")
            return _err("QUOTA_EXCEEDED", "Backup quota exceeded: at most 20 created backups per project.")

        # snapshot tasks + dependencies (all rows for project, include deleted too for fidelity)
        snapshot_tasks = [t for t in tasks if isinstance(t, dict) and t.get("project_id") == project_id]
        snapshot_deps = [d for d in deps if isinstance(d, dict) and d.get("project_id") == project_id]
        bak = {
            "id": _gen_id("cot_bak_"),
            "project_id": project_id,
            "reason": backup_reason,
            "status": "created",
            "snapshot": {"tasks": snapshot_tasks, "dependencies": snapshot_deps},
            "retention_expires_at": (datetime.datetime.utcnow().replace(microsecond=0) + datetime.timedelta(days=14)).isoformat() + "Z",
            "created_at": _now(),
            "updated_at": _now(),
        }
        backups.append(bak)

        # soft-delete all unfinished tasks and remove dependencies involving deleted tasks
        now = _now()
        deleted_task_ids = set()
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("project_id") != project_id:
                continue
            if t.get("deleted_at") is not None:
                continue
            if t.get("status") != "completed":
                t["deleted_at"] = now
                t["updated_at"] = now
                deleted_task_ids.add(t.get("id"))

        if deleted_task_ids:
            new_deps = []
            for d in deps:
                if not isinstance(d, dict):
                    continue
                if d.get("project_id") != project_id:
                    new_deps.append(d)
                    continue
                if d.get("task_id") in deleted_task_ids or d.get("depends_on_task_id") in deleted_task_ids:
                    continue
                new_deps.append(d)
            deps = new_deps

        # persist backup and clears
        _save("task_backups.json", backups)
        _save("tasks.json", tasks)
        _save("task_dependencies.json", deps)

    # Generate a minimal deterministic-ish plan from root task (no LLM): create up to max_tasks tasks
    # Names must be unique per project among non-deleted tasks.
    active_tasks = [t for t in tasks if isinstance(t, dict) and t.get("project_id") == project_id and t.get("deleted_at") is None]
    active_name_set = set([t.get("name") for t in active_tasks if isinstance(t.get("name"), str)])
    active_count = len(active_tasks)
    project_task_quota = 500
    remaining_capacity = project_task_quota - active_count
    if remaining_capacity <= 0:
        _log("error", "QUOTA_EXCEEDED", "Project task quota exceeded: at most 500 non-deleted tasks.")
        return _err("QUOTA_EXCEEDED", "Project task quota exceeded: at most 500 non-deleted tasks.")

    n = max_tasks if isinstance(max_tasks, int) else 5
    n = max(1, min(n, remaining_capacity))

    base = root_task.get("name") if isinstance(root_task.get("name"), str) and root_task.get("name").strip() else "Root Task"
    plan = []
    for i in range(1, n + 1):
        nm = f"{base} - Subtask {i}"
        if nm in active_name_set:
            # find an unused suffix
            j = 2
            while f"{nm} ({j})" in active_name_set:
                j += 1
            nm = f"{nm} ({j})"
        active_name_set.add(nm)
        plan.append({
            "name": nm,
            "description": None,
            "notes": None,
            "priority": 3,
            "status": "planned",
            "implementation_guide": None,
            "verification_criteria": None,
            "related_files": [],
        })

    def _task_by_name_active(nm):
        for t in tasks:
            if isinstance(t, dict) and t.get("project_id") == project_id and t.get("deleted_at") is None and t.get("name") == nm:
                return t
        return None

    created = []
    updated = []
    now = _now()

    # Apply plan per updateMode
    if updateMode == "append":
        # only insert; do not touch existing, do not require root_task to belong to project
        for p in plan:
            if _task_by_name_active(p["name"]) is not None:
                # skip if name already exists (append is insert-only)
                continue
            if len([t for t in tasks if isinstance(t, dict) and t.get("project_id") == project_id and t.get("deleted_at") is None]) >= 500:
                _log("error", "QUOTA_EXCEEDED", "Project task quota exceeded: at most 500 non-deleted tasks.")
                return _err("QUOTA_EXCEEDED", "Project task quota exceeded: at most 500 non-deleted tasks.")
            row = {
                "id": _gen_id("cot_tsk_"),
                "project_id": project_id,
                "name": p["name"],
                "description": p["description"],
                "notes": p["notes"],
                "priority": p["priority"],
                "status": p["status"],
                "implementation_guide": p["implementation_guide"],
                "verification_criteria": p["verification_criteria"],
                "related_files": p["related_files"],
                "summary": None,
                "completion_report": None,
                "completed_at": None,
                "deleted_at": None,
                "created_at": now,
                "updated_at": now,
            }
            tasks.append(row)
            created.append(row)
    elif updateMode == "selective":
        # match by (project_id, name) to update existing unfinished tasks and insert missing
        for p in plan:
            existing = _task_by_name_active(p["name"])
            if existing is None:
                if len([t for t in tasks if isinstance(t, dict) and t.get("project_id") == project_id and t.get("deleted_at") is None]) >= 500:
                    _log("error", "QUOTA_EXCEEDED", "Project task quota exceeded: at most 500 non-deleted tasks.")
                    return _err("QUOTA_EXCEEDED", "Project task quota exceeded: at most 500 non-deleted tasks.")
                row = {
                    "id": _gen_id("cot_tsk_"),
                    "project_id": project_id,
                    "name": p["name"],
                    "description": p["description"],
                    "notes": p["notes"],
                    "priority": p["priority"],
                    "status": p["status"],
                    "implementation_guide": p["implementation_guide"],
                    "verification_criteria": p["verification_criteria"],
                    "related_files": p["related_files"],
                    "summary": None,
                    "completion_report": None,
                    "completed_at": None,
                    "deleted_at": None,
                    "created_at": now,
                    "updated_at": now,
                }
                tasks.append(row)
                created.append(row)
            else:
                if existing.get("status") == "completed":
                    continue  # do not update completed tasks in selective mode
                existing["description"] = p["description"]
                existing["notes"] = p["notes"]
                existing["priority"] = p["priority"]
                # Do not force status transitions here; keep current status unless it's cancelled and plan wants planned
                if existing.get("status") in ("planned", "ready", "blocked", "in_progress", "cancelled"):
                    existing["status"] = existing.get("status") or "planned"
                existing["implementation_guide"] = p["implementation_guide"]
                existing["verification_criteria"] = p["verification_criteria"]
                existing["related_files"] = p["related_files"]
                existing["updated_at"] = now
                updated.append(existing)
    elif updateMode in ("overwrite", "clearAllTasks"):
        # already cleared unfinished tasks above; now insert all planned tasks
        for p in plan:
            if len([t for t in tasks if isinstance(t, dict) and t.get("project_id") == project_id and t.get("deleted_at") is None]) >= 500:
                _log("error", "QUOTA_EXCEEDED", "Project task quota exceeded: at most 500 non-deleted tasks.")
                return _err("QUOTA_EXCEEDED", "Project task quota exceeded: at most 500 non-deleted tasks.")
            row = {
                "id": _gen_id("cot_tsk_"),
                "project_id": project_id,
                "name": p["name"],
                "description": p["description"],
                "notes": p["notes"],
                "priority": p["priority"],
                "status": p["status"],
                "implementation_guide": p["implementation_guide"],
                "verification_criteria": p["verification_criteria"],
                "related_files": p["related_files"],
                "summary": None,
                "completion_report": None,
                "completed_at": None,
                "deleted_at": None,
                "created_at": now,
                "updated_at": now,
            }
            tasks.append(row)
            created.append(row)
    else:
        _log("error", "VALIDATION_ERROR", "Invalid updateMode.")
        return _err("VALIDATION_ERROR", "Invalid updateMode.")

    # Dependencies creation: chain blocks between created+updated in plan order (only among tasks in this project)
    created_deps = []
    if create_dependencies:
        # Build list of actual task rows for plan in order (created or existing by name)
        plan_rows = []
        for p in plan:
            row = _task_by_name_active(p["name"])
            if row is not None:
                plan_rows.append(row)
        # Create blocks edges: task[i] depends on task[i-1]
        # Enforce per-task dependency cap <= 50
        # Enforce no self, unique, same project, no cycles (chain is acyclic)
        if len(plan_rows) >= 2:
            # precompute outgoing dep counts
            out_counts = {}
            for d in deps:
                if isinstance(d, dict) and d.get("project_id") == project_id and d.get("task_id") and d.get("depends_on_task_id"):
                    out_counts[d["task_id"]] = out_counts.get(d["task_id"], 0) + 1

            existing_pairs = set()
            for d in deps:
                if isinstance(d, dict) and d.get("project_id") == project_id:
                    existing_pairs.add((d.get("task_id"), d.get("depends_on_task_id")))

            for i in range(1, len(plan_rows)):
                t = plan_rows[i]
                dep_on = plan_rows[i - 1]
                if t.get("id") == dep_on.get("id"):
                    continue
                if (t.get("id"), dep_on.get("id")) in existing_pairs:
                    continue
                if out_counts.get(t.get("id"), 0) >= 50:
                    _log("error", "QUOTA_EXCEEDED", "A task may have at most 50 dependencies.", task_id=t.get("id"))
                    return _err("QUOTA_EXCEEDED", "A task may have at most 50 dependencies.", task_id=t.get("id"))
                # both must be non-deleted
                if t.get("deleted_at") is not None or dep_on.get("deleted_at") is not None:
                    continue
                row = {
                    "id": _gen_id("cot_dep_"),
                    "project_id": project_id,
                    "task_id": t.get("id"),
                    "depends_on_task_id": dep_on.get("id"),
                    "dependency_type": "blocks",
                    "created_at": now,
                    "updated_at": now,
                }
                deps.append(row)
                created_deps.append(row)
                existing_pairs.add((t.get("id"), dep_on.get("id")))
                out_counts[t.get("id")] = out_counts.get(t.get("id"), 0) + 1

    _save("tasks.json", tasks)
    _save("task_dependencies.json", deps)

    # Create a thought session row for audit trail
    ths = _load("thought_sessions.json")
    if not isinstance(ths, list):
        ths = []
    session = {
        "id": _gen_id("cot_ths_"),
        "project_id": project_id,
        "root_task_id": root_task_id,
        "mode": "split_tasks",
        "status": "closed",
        "summary": f"Applied split_tasks with updateMode={updateMode}; created={len(created)} updated={len(updated)} deps_created={len(created_deps)}.",
        "next_thought_needed": False,
        "created_at": now,
        "updated_at": now,
        "closed_at": now,
    }
    ths.append(session)
    _save("thought_sessions.json", ths)

    resp = {
        "thought_session": session,
        "tasks_created": created,
        "tasks_updated": updated,
        "dependencies_created": created_deps,
        "meta": {
            "project_id": project_id,
            "root_task_id": root_task_id,
            "updateMode": updateMode,
            "max_tasks": max_tasks,
            "create_dependencies": bool(create_dependencies),
        },
    }
    _log("ok", meta={"created": len(created), "updated": len(updated), "deps_created": len(created_deps)})
    return resp

def list_tasks(project_id, status=None, include_deleted=None, include_dependencies=None, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if "offset" not in obj:
                return None
            off = obj["offset"]
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        payload = json.dumps({"offset": off}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "list_tasks"
    status_code = "success"

    # Defaults
    if include_deleted is None:
        include_deleted = False
    if include_dependencies is None:
        include_dependencies = False
    if sort is None:
        sort = "priority"
    if order is None:
        order = "asc"
    if limit is None:
        limit = 50

    # Validate
    if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
        status_code = "error"
        return _err("VALIDATION_ERROR", "Invalid project_id format.")
    if status is not None:
        if not isinstance(status, str) or status not in ["planned", "ready", "in_progress", "blocked", "completed", "cancelled"]:
            status_code = "error"
            return _err("VALIDATION_ERROR", "Invalid status value.")
    if not isinstance(include_deleted, bool):
        status_code = "error"
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean.")
    if not isinstance(include_dependencies, bool):
        status_code = "error"
        return _err("VALIDATION_ERROR", "include_dependencies must be a boolean.")
    if sort not in ["priority", "created_at", "updated_at", "status", "name"]:
        status_code = "error"
        return _err("VALIDATION_ERROR", "Invalid sort value.")
    if order not in ["asc", "desc"]:
        status_code = "error"
        return _err("VALIDATION_ERROR", "Invalid order value.")
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        status_code = "error"
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and (not isinstance(cursor, str) or cursor == ""):
        status_code = "error"
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    # Load
    projects = _load("projects.json")
    tasks = _load("tasks.json")
    deps = _load("task_dependencies.json")
    sessions = _load("thought_sessions.json")

    project = next((p for p in projects if p.get("id") == project_id), None)
    if not project:
        status_code = "error"
        # audit
        try:
            sessions.append({
                "id": f"cot_ths_AUDIT_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{int(time.time()*1000)}",
                "project_id": project_id,
                "root_task_id": None,
                "mode": "process_thought",
                "status": "failed",
                "summary": json.dumps({"endpoint": endpoint, "status": "NOT_FOUND", "message": "Project not found."}, ensure_ascii=False),
                "next_thought_needed": False,
                "created_at": _now(),
                "updated_at": _now(),
                "closed_at": _now()
            })
            _save("thought_sessions.json", sessions)
        except Exception:
            pass
        return _err("NOT_FOUND", "Project not found.")

    # Filter
    rows = []
    for t in tasks:
        if t.get("project_id") != project_id:
            continue
        if not include_deleted and t.get("deleted_at") is not None:
            continue
        if status is not None and t.get("status") != status:
            continue
        rows.append(t)

    # Precompute dependency counts / edges if requested
    dep_by_task_out = {}
    dep_by_task_in = {}
    if include_dependencies:
        for d in deps:
            if d.get("project_id") != project_id:
                continue
            tid = d.get("task_id")
            did = d.get("depends_on_task_id")
            dep_by_task_out.setdefault(tid, []).append(d)
            dep_by_task_in.setdefault(did, []).append(d)

    # Sort
    reverse = (order == "desc")

    def _key(v):
        x = v.get(sort)
        # stable and safe ordering across types
        if x is None:
            return ""
        return x

    # For priority, keep numeric ordering
    if sort == "priority":
        def _key(v):
            x = v.get("priority")
            if isinstance(x, int):
                return x
            return 10**9
    rows.sort(key=_key, reverse=reverse)

    # Pagination
    off = _parse_cursor(cursor) if cursor is not None else 0
    if cursor is not None and off is None:
        status_code = "error"
        # audit
        try:
            sessions.append({
                "id": f"cot_ths_AUDIT_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{int(time.time()*1000)}",
                "project_id": project_id,
                "root_task_id": None,
                "mode": "process_thought",
                "status": "failed",
                "summary": json.dumps({"endpoint": endpoint, "status": "VALIDATION_ERROR", "message": "Invalid cursor."}, ensure_ascii=False),
                "next_thought_needed": False,
                "created_at": _now(),
                "updated_at": _now(),
                "closed_at": _now()
            })
            _save("thought_sessions.json", sessions)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(rows)
    page = rows[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    # Build response items with derived dependency counts/data
    items = []
    for t in page:
        item = dict(t)
        # derived counts always returned (service convenience), deps optionally
        out_edges = dep_by_task_out.get(t.get("id"), []) if include_dependencies else []
        in_edges = dep_by_task_in.get(t.get("id"), []) if include_dependencies else []
        item["dependency_counts"] = {
            "outgoing": len(out_edges) if include_dependencies else sum(1 for d in deps if d.get("project_id") == project_id and d.get("task_id") == t.get("id")),
            "incoming": len(in_edges) if include_dependencies else sum(1 for d in deps if d.get("project_id") == project_id and d.get("depends_on_task_id") == t.get("id"))
        }
        if include_dependencies:
            item["dependencies"] = {
                "outgoing": out_edges,
                "incoming": in_edges
            }
        items.append(item)

    # Audit via thought_sessions (no dedicated audit collection in schema)
    try:
        latency_ms = int((time.time() - t0) * 1000)
        sessions.append({
            "id": f"cot_ths_AUDIT_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{int(time.time()*1000)}",
            "project_id": project_id,
            "root_task_id": None,
            "mode": "process_thought",
            "status": "closed",
            "summary": json.dumps({"endpoint": endpoint, "status": status_code, "latency_ms": latency_ms}, ensure_ascii=False),
            "next_thought_needed": False,
            "created_at": _now(),
            "updated_at": _now(),
            "closed_at": _now()
        })
        _save("thought_sessions.json", sessions)
    except Exception:
        pass

    return {
        "object": "list",
        "data": items,
        "project_id": project_id,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "order": order
    }

def execute_task(project_id, task_id, session_id=None, notes=None, update_status=None, **_extra):
    import json, os, datetime, re, time, base64, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    t0 = time.time()
    endpoint = "execute_task"
    status_code = "success"

    if update_status is None:
        update_status = True

    # Validate
    if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
        status_code = "error"
        return _err("VALIDATION_ERROR", "Invalid project_id format.")
    if not isinstance(task_id, str) or not re.match(r"^cot_tsk_[0-9A-Z]{18,}$", task_id):
        status_code = "error"
        return _err("VALIDATION_ERROR", "Invalid task_id format.")
    if session_id is not None and (not isinstance(session_id, str) or not re.match(r"^cot_ths_[0-9A-Z]{18,}$", session_id)):
        status_code = "error"
        return _err("VALIDATION_ERROR", "Invalid session_id format.")
    if notes is not None and not isinstance(notes, str):
        status_code = "error"
        return _err("VALIDATION_ERROR", "notes must be a string.")
    if not isinstance(update_status, bool):
        status_code = "error"
        return _err("VALIDATION_ERROR", "update_status must be a boolean.")

    projects = _load("projects.json")
    tasks = _load("tasks.json")
    deps = _load("task_dependencies.json")
    sessions = _load("thought_sessions.json")

    project = next((p for p in projects if p.get("id") == project_id), None)
    if not project:
        status_code = "error"
        # audit
        try:
            sessions.append({
                "id": f"cot_ths_AUDIT_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{int(time.time()*1000)}",
                "project_id": project_id,
                "root_task_id": None,
                "mode": "process_thought",
                "status": "failed",
                "summary": json.dumps({"endpoint": endpoint, "status": "NOT_FOUND", "message": "Project not found."}, ensure_ascii=False),
                "next_thought_needed": False,
                "created_at": _now(),
                "updated_at": _now(),
                "closed_at": _now()
            })
            _save("thought_sessions.json", sessions)
        except Exception:
            pass
        return _err("NOT_FOUND", "Project not found.")

    task = next((t for t in tasks if t.get("id") == task_id and t.get("project_id") == project_id), None)
    if not task or task.get("deleted_at") is not None:
        status_code = "error"
        # audit
        try:
            sessions.append({
                "id": f"cot_ths_AUDIT_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{int(time.time()*1000)}",
                "project_id": project_id,
                "root_task_id": task_id,
                "mode": "process_thought",
                "status": "failed",
                "summary": json.dumps({"endpoint": endpoint, "status": "NOT_FOUND", "message": "Task not found."}, ensure_ascii=False),
                "next_thought_needed": False,
                "created_at": _now(),
                "updated_at": _now(),
                "closed_at": _now()
            })
            _save("thought_sessions.json", sessions)
        except Exception:
            pass
        return _err("NOT_FOUND", "Task not found.")

    # Resolve/create session
    session = None
    if session_id is not None:
        session = next((s for s in sessions if s.get("id") == session_id), None)
        if not session:
            status_code = "error"
            return _err("NOT_FOUND", "Session not found.")
        if session.get("project_id") != project_id:
            status_code = "error"
            return _err("NOT_FOUND", "Session does not belong to the specified project.")
        if session.get("root_task_id") is not None and session.get("root_task_id") != task_id:
            status_code = "error"
            return _err("CONFLICT", "Session is bound to a different task.")
        if session.get("status") != "open":
            status_code = "error"
            return _err("INVALID_TRANSITION", "Cannot append execution to a non-open session.")
        # enforce mode? allow but keep consistent with tool
        if session.get("mode") != "execute_task":
            # vendor behavior often creates separate session; here, conflict to avoid mixing intents
            status_code = "error"
            return _err("CONFLICT", "Session mode mismatch; expected execute_task.")
    else:
        sid = _gen_id("cot_ths_")
        now = _now()
        session = {
            "id": sid,
            "project_id": project_id,
            "root_task_id": task_id,
            "mode": "execute_task",
            "status": "open",
            "summary": None,
            "next_thought_needed": True,
            "created_at": now,
            "updated_at": now,
            "closed_at": None
        }
        sessions.append(session)

    # Determine if blockers complete
    blockers = [d for d in deps if d.get("project_id") == project_id and d.get("task_id") == task_id and d.get("dependency_type") == "blocks"]
    blocker_task_ids = [d.get("depends_on_task_id") for d in blockers]
    blocker_tasks = [t for t in tasks if t.get("project_id") == project_id and t.get("id") in blocker_task_ids and t.get("deleted_at") is None]
    blocker_map = {t.get("id"): t for t in blocker_tasks}

    unmet = []
    for bid in blocker_task_ids:
        bt = blocker_map.get(bid)
        # If referenced blocker task missing/non-active, treat as unmet (FK integrity should prevent this, but be safe)
        if not bt or bt.get("status") != "completed":
            unmet.append(bid)

    task_changes = None
    # Update task status if requested
    if update_status:
        prev_status = task.get("status")
        now = _now()

        # If already completed/cancelled, don't transition
        if prev_status in ("completed", "cancelled"):
            # no mutation, but session can still record execution attempt
            pass
        else:
            if len(unmet) == 0:
                # allow transition to in_progress from planned/ready/blocked per business rule
                if prev_status in ("planned", "ready", "blocked", "in_progress"):
                    if prev_status != "in_progress":
                        task["status"] = "in_progress"
                        task["updated_at"] = now
                        task_changes = {"task_id": task_id, "from": prev_status, "to": "in_progress"}
                else:
                    status_code = "error"
                    return _err("INVALID_TRANSITION", f"Cannot transition task from {prev_status} to in_progress.")
            else:
                # must set blocked
                if prev_status in ("planned", "ready", "in_progress", "blocked"):
                    if prev_status != "blocked":
                        task["status"] = "blocked"
                        task["updated_at"] = now
                        task_changes = {"task_id": task_id, "from": prev_status, "to": "blocked", "unmet_blockers": unmet}
                else:
                    status_code = "error"
                    return _err("INVALID_TRANSITION", f"Cannot transition task from {prev_status} to blocked.")

    # Update session summary and close it (execute tool records an operation; close when done)
    now = _now()
    session["summary"] = json.dumps({
        "endpoint": endpoint,
        "task_id": task_id,
        "notes": notes,
        "update_status": update_status,
        "blockers_total": len(blocker_task_ids),
        "unmet_blockers": unmet,
        "task_status_change": task_changes
    }, ensure_ascii=False)
    session["next_thought_needed"] = False
    session["status"] = "closed"
    session["updated_at"] = now
    session["closed_at"] = now

    # Persist
    _save("tasks.json", tasks)
    _save("thought_sessions.json", sessions)

    # Audit
    try:
        latency_ms = int((time.time() - t0) * 1000)
        audit = {
            "id": f"cot_ths_AUDIT_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{int(time.time()*1000)}",
            "project_id": project_id,
            "root_task_id": task_id,
            "mode": "process_thought",
            "status": "closed",
            "summary": json.dumps({"endpoint": endpoint, "status": status_code, "latency_ms": latency_ms}, ensure_ascii=False),
            "next_thought_needed": False,
            "created_at": _now(),
            "updated_at": _now(),
            "closed_at": _now()
        }
        sessions.append(audit)
        _save("thought_sessions.json", sessions)
    except Exception:
        pass

    return {
        "session": session,
        "task": task,
        "task_status_change": task_changes
    }

