def complete_task(project_id, task_id, completion_report, summary=None, notes=None, completed_at=None, update_dependents=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "complete_task"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
            else:
                dt = datetime.datetime.fromisoformat(s)
            return dt.replace(microsecond=0).isoformat() + "Z"
        except Exception:
            return None

    def _parse_ts(s):
        try:
            if isinstance(s, str) and s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid_like(n=22):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return "".join(secrets.choice(alphabet) for _ in range(n))

    def _gen_id(prefix):
        return prefix + _ulid_like(22)

    def _log(status, code=None, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("cot_rql_"),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "project_id": project_id if isinstance(project_id, str) else None,
            "task_id": task_id if isinstance(task_id, str) else None,
        }
        if code or message:
            row["error"] = {"code": code, "message": message}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if r.get("project_id") != project_id:
                continue
            ts = _parse_ts(r.get("timestamp") or r.get("ts"))
            if ts and ts >= cutoff:
                cnt += 1
                if cnt >= 120:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    # Validate
    if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
        _log("error", "VALIDATION_ERROR", "Invalid project_id format.")
        return _err("VALIDATION_ERROR", "Invalid project_id format.")
    if not isinstance(task_id, str) or not re.match(r"^cot_tsk_[0-9A-Z]{18,}$", task_id):
        _log("error", "VALIDATION_ERROR", "Invalid task_id format.")
        return _err("VALIDATION_ERROR", "Invalid task_id format.")
    if completion_report is None or not isinstance(completion_report, dict):
        _log("error", "VALIDATION_ERROR", "completion_report must be an object.")
        return _err("VALIDATION_ERROR", "completion_report must be an object.")
    if summary is not None and not isinstance(summary, str):
        _log("error", "VALIDATION_ERROR", "summary must be a string.")
        return _err("VALIDATION_ERROR", "summary must be a string.")
    if notes is not None and not isinstance(notes, str):
        _log("error", "VALIDATION_ERROR", "notes must be a string.")
        return _err("VALIDATION_ERROR", "notes must be a string.")
    if update_dependents is None:
        update_dependents = True
    if not isinstance(update_dependents, bool):
        _log("error", "VALIDATION_ERROR", "update_dependents must be a boolean.")
        return _err("VALIDATION_ERROR", "update_dependents must be a boolean.")
    if completed_at is not None:
        parsed = _parse_dt(completed_at)
        if parsed is None:
            _log("error", "VALIDATION_ERROR", "completed_at must be a valid date-time string.")
            return _err("VALIDATION_ERROR", "completed_at must be a valid date-time string.")
        completed_at_norm = parsed
    else:
        completed_at_norm = _now()

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if prj is None:
        _log("error", "NOT_FOUND", "Project not found.")
        return _err("NOT_FOUND", "Project not found.")

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    deps = _load("task_dependencies.json")
    if not isinstance(deps, list):
        deps = []

    task = next((t for t in tasks if isinstance(t, dict) and t.get("id") == task_id and t.get("project_id") == project_id and t.get("deleted_at") is None), None)
    if task is None:
        _log("error", "NOT_FOUND", "Task not found.")
        return _err("NOT_FOUND", "Task not found.")

    if task.get("status") == "completed":
        # idempotent-ish: if already completed, don't rewrite; return current row
        _log("success", meta={"idempotent": True})
        return {"task": task}

    # blocks dependencies must be completed
    blockers = [d for d in deps if isinstance(d, dict) and d.get("project_id") == project_id and d.get("task_id") == task_id and d.get("dependency_type") == "blocks"]
    if blockers:
        blocker_ids = [d.get("depends_on_task_id") for d in blockers if isinstance(d.get("depends_on_task_id"), str)]
        blocker_tasks = {t.get("id"): t for t in tasks if isinstance(t, dict) and t.get("project_id") == project_id and t.get("deleted_at") is None and t.get("id") in blocker_ids}
        incomplete = [bid for bid in blocker_ids if bid not in blocker_tasks or blocker_tasks[bid].get("status") != "completed"]
        if incomplete:
            _log("error", "INVALID_TRANSITION", "Cannot complete task: not all 'blocks' dependencies are completed.", meta={"incomplete_blockers": incomplete})
            return _err("INVALID_TRANSITION", "Cannot complete task: not all 'blocks' dependencies are completed.", incomplete_blockers=incomplete)

    # Complete the task
    ts = _now()
    task["status"] = "completed"
    task["completed_at"] = completed_at_norm
    task["completion_report"] = completion_report
    if summary is not None:
        task["summary"] = summary
    if notes is not None:
        task["notes"] = notes
    task["updated_at"] = ts

    # Update dependents: any task that depends (blocks) on this one may become ready if all blockers completed
    updated_dependents = []
    if update_dependents:
        outgoing = [d for d in deps if isinstance(d, dict) and d.get("project_id") == project_id and d.get("depends_on_task_id") == task_id and d.get("dependency_type") == "blocks"]
        dependent_ids = [d.get("task_id") for d in outgoing if isinstance(d.get("task_id"), str)]
        for dep_id in dependent_ids:
            dep_task = next((t for t in tasks if isinstance(t, dict) and t.get("id") == dep_id and t.get("project_id") == project_id and t.get("deleted_at") is None), None)
            if not dep_task:
                continue
            if dep_task.get("status") not in ("planned", "blocked"):
                continue
            # check all blockers of dep_task
            dep_blockers = [d for d in deps if isinstance(d, dict) and d.get("project_id") == project_id and d.get("task_id") == dep_id and d.get("dependency_type") == "blocks"]
            if not dep_blockers:
                dep_task["status"] = "ready"
                dep_task["updated_at"] = ts
                updated_dependents.append(dep_task)
                continue
            ok = True
            for bd in dep_blockers:
                bid = bd.get("depends_on_task_id")
                bt = next((t for t in tasks if isinstance(t, dict) and t.get("id") == bid and t.get("project_id") == project_id and t.get("deleted_at") is None), None)
                if not bt or bt.get("status") != "completed":
                    ok = False
                    break
            if ok:
                dep_task["status"] = "ready"
                dep_task["updated_at"] = ts
                updated_dependents.append(dep_task)

    _save("tasks.json", tasks)

    _log("success", meta={"updated_dependents": len(updated_dependents)})
    return {"task": task, "updated_dependents": updated_dependents}

def delete_task(project_id, task_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, status, latency_ms, meta=None):
        fn = _ensure_request_log()
        logs = _load(fn)
        row = {
            "id": "cot_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    t0 = time.time()
    endpoint = "delete_task"

    try:
        if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "project_id"})
            return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
        if not isinstance(task_id, str) or not re.match(r"^cot_tsk_[0-9A-Z]{18,}$", task_id):
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "task_id"})
            return _err("VALIDATION_ERROR", "Malformed task_id.", field="task_id")
    except Exception:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid input.")

    projects = _load("projects.json")
    if not any(p.get("id") == project_id for p in projects):
        _log(endpoint, "NOT_FOUND", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    tasks = _load("tasks.json")
    idx = None
    for i, t in enumerate(tasks):
        if t.get("id") == task_id and t.get("project_id") == project_id:
            idx = i
            break
    if idx is None:
        _log(endpoint, "NOT_FOUND", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Task not found.", project_id=project_id, task_id=task_id)

    task = tasks[idx]
    if task.get("deleted_at") is not None:
        _log(endpoint, "CONFLICT", (time.time() - t0) * 1000)
        return _err("CONFLICT", "Task is already deleted.", task_id=task_id)

    status = task.get("status")
    if status == "completed":
        _log(endpoint, "CONFLICT", (time.time() - t0) * 1000)
        return _err("CONFLICT", "Cannot delete a completed task.", task_id=task_id, status=status)

    allowed = {"planned", "ready", "in_progress", "blocked", "cancelled"}
    if status not in allowed:
        _log(endpoint, "CONFLICT", (time.time() - t0) * 1000)
        return _err("CONFLICT", "Task is not deletable in its current state.", task_id=task_id, status=status)

    # Soft-delete task
    now = _now()
    task["deleted_at"] = now
    task["updated_at"] = now
    tasks[idx] = task

    # Remove dependencies involving this task (FK integrity rule)
    deps = _load("task_dependencies.json")
    before = len(deps)
    deps = [d for d in deps if not (d.get("project_id") == project_id and (d.get("task_id") == task_id or d.get("depends_on_task_id") == task_id))]
    after = len(deps)

    _save("tasks.json", tasks)
    if after != before:
        _save("task_dependencies.json", deps)

    _log(endpoint, "OK", (time.time() - t0) * 1000, {"removed_dependency_edges": before - after})

    return {"task": task}

def clear_all_tasks(project_id, reason=None, **_extra):
    import json, os, datetime, re, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, status, latency_ms, meta=None):
        fn = _ensure_request_log()
        logs = _load(fn)
        row = {
            "id": "cot_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _gen_id(prefix):
        # 18+ chars uppercase alnum after prefix
        alphabet = string.ascii_uppercase + string.digits
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    t0 = time.time()
    endpoint = "clear_all_tasks"

    try:
        if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "project_id"})
            return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
        if reason is not None and reason != "clear_all_tasks":
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "reason"})
            return _err("VALIDATION_ERROR", "Invalid reason; must be 'clear_all_tasks'.", field="reason")
        if reason is None:
            reason = "clear_all_tasks"
    except Exception:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid input.")

    projects = _load("projects.json")
    if not any(p.get("id") == project_id for p in projects):
        _log(endpoint, "NOT_FOUND", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    tasks = _load("tasks.json")
    deps = _load("task_dependencies.json")
    backups = _load("task_backups.json")

    # Backup quota: at most 20 backups per project with status='created'
    active_backups = [b for b in backups if b.get("project_id") == project_id and b.get("status") == "created"]
    if len(active_backups) >= 20:
        _log(endpoint, "QUOTA_EXCEEDED", (time.time() - t0) * 1000, {"quota": "backups_per_project", "limit": 20})
        return _err("QUOTA_EXCEEDED", "Backup quota exceeded for project.", project_id=project_id, limit=20)

    # Snapshot: tasks (all) + dependencies (all) for the project at time of backup
    proj_tasks = [t for t in tasks if t.get("project_id") == project_id]
    proj_deps = [d for d in deps if d.get("project_id") == project_id]
    snapshot = {"tasks": proj_tasks, "dependencies": proj_deps}

    now = _now()
    backup_row = {
        "id": _gen_id("cot_bak_"),
        "project_id": project_id,
        "reason": reason,
        "status": "created",
        "snapshot": snapshot,
        "retention_expires_at": None,
        "created_at": now,
        "updated_at": now,
    }
    backups.append(backup_row)

    # Soft-delete all tasks where status <> 'completed'
    # and remove dependencies involving deleted tasks
    unfinished_ids = set()
    updated = 0
    for t in tasks:
        if t.get("project_id") != project_id:
            continue
        if t.get("status") != "completed" and t.get("deleted_at") is None:
            t["deleted_at"] = now
            t["updated_at"] = now
            unfinished_ids.add(t.get("id"))
            updated += 1

    # Remove dependencies where either endpoint is deleted (or in this unfinished_ids set)
    before_deps = len(deps)
    deps = [d for d in deps if not (d.get("project_id") == project_id and (d.get("task_id") in unfinished_ids or d.get("depends_on_task_id") in unfinished_ids))]
    removed_deps = before_deps - len(deps)

    if updated == 0 and removed_deps == 0:
        # Still created a backup; that's an effect. But real behavior: operation should still succeed.
        pass

    _save("task_backups.json", backups)
    _save("tasks.json", tasks)
    if removed_deps:
        _save("task_dependencies.json", deps)

    _log(endpoint, "OK", (time.time() - t0) * 1000, {"soft_deleted_tasks": updated, "removed_dependency_edges": removed_deps, "backup_id": backup_row["id"]})

    return {
        "backup": backup_row,
        "result": {
            "soft_deleted_tasks": updated,
            "removed_dependency_edges": removed_deps,
        },
    }

def update_task(project_id, task_id, name=None, description=None, notes=None, priority=None, status=None, implementation_guide=None, verification_criteria=None, related_files=None, summary=None, dependency_updates=None, completion_report=None, completed_at=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_task"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(22))

    def _parse_dt_str(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
            else:
                dt = datetime.datetime.fromisoformat(s)
            return dt.replace(microsecond=0).isoformat() + "Z"
        except Exception:
            return None

    def _log(status, code=None, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("cot_rql_"),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "project_id": project_id if isinstance(project_id, str) else None,
            "task_id": task_id if isinstance(task_id, str) else None,
        }
        if code or message:
            row["error"] = {"code": code, "message": message}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Rate limit: 240/min per project per endpoint (best-effort if request_logs.json absent)
    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if r.get("project_id") != project_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]) if ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= 240:
            return _err("RATE_LIMIT", "Rate limit exceeded for this endpoint (240/min).")
        return None

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
        _log("error", "VALIDATION_ERROR", "Invalid project_id format.")
        return _err("VALIDATION_ERROR", "Invalid project_id format.")
    if not isinstance(task_id, str) or not re.match(r"^cot_tsk_[0-9A-Z]{18,}$", task_id):
        _log("error", "VALIDATION_ERROR", "Invalid task_id format.")
        return _err("VALIDATION_ERROR", "Invalid task_id format.")
    if name is not None and (not isinstance(name, str) or name.strip() == ""):
        _log("error", "VALIDATION_ERROR", "name must be a non-empty string.")
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if description is not None and not isinstance(description, str):
        _log("error", "VALIDATION_ERROR", "description must be a string.")
        return _err("VALIDATION_ERROR", "description must be a string.")
    if notes is not None and not isinstance(notes, str):
        _log("error", "VALIDATION_ERROR", "notes must be a string.")
        return _err("VALIDATION_ERROR", "notes must be a string.")
    if implementation_guide is not None and not isinstance(implementation_guide, str):
        _log("error", "VALIDATION_ERROR", "implementation_guide must be a string.")
        return _err("VALIDATION_ERROR", "implementation_guide must be a string.")
    if verification_criteria is not None and not isinstance(verification_criteria, str):
        _log("error", "VALIDATION_ERROR", "verification_criteria must be a string.")
        return _err("VALIDATION_ERROR", "verification_criteria must be a string.")
    if summary is not None and not isinstance(summary, str):
        _log("error", "VALIDATION_ERROR", "summary must be a string.")
        return _err("VALIDATION_ERROR", "summary must be a string.")
    if priority is not None:
        if not isinstance(priority, int):
            _log("error", "VALIDATION_ERROR", "priority must be an integer.")
            return _err("VALIDATION_ERROR", "priority must be an integer.")
        if priority < 1 or priority > 5:
            _log("error", "VALIDATION_ERROR", "priority must be between 1 and 5.")
            return _err("VALIDATION_ERROR", "priority must be between 1 and 5.")
    allowed_status = {"planned", "ready", "in_progress", "blocked", "completed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log("error", "VALIDATION_ERROR", "Invalid status value.")
        return _err("VALIDATION_ERROR", "Invalid status value.")
    if related_files is not None:
        if not isinstance(related_files, list) or any((not isinstance(x, str)) for x in related_files):
            _log("error", "VALIDATION_ERROR", "related_files must be an array of strings.")
            return _err("VALIDATION_ERROR", "related_files must be an array of strings.")
        if len(related_files) > 200:
            _log("error", "VALIDATION_ERROR", "related_files length must be <= 200.")
            return _err("VALIDATION_ERROR", "related_files length must be <= 200.")
    if dependency_updates is not None and not isinstance(dependency_updates, dict):
        _log("error", "VALIDATION_ERROR", "dependency_updates must be an object.")
        return _err("VALIDATION_ERROR", "dependency_updates must be an object.")
    if completion_report is not None and not isinstance(completion_report, dict):
        _log("error", "VALIDATION_ERROR", "completion_report must be an object.")
        return _err("VALIDATION_ERROR", "completion_report must be an object.")
    if completed_at is not None:
        if not isinstance(completed_at, str) or _parse_dt_str(completed_at) is None:
            _log("error", "VALIDATION_ERROR", "completed_at must be an RFC3339 datetime string.")
            return _err("VALIDATION_ERROR", "completed_at must be an RFC3339 datetime string.")

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    # Load datastore rows
    projects = _load("projects.json")
    tasks = _load("tasks.json")
    deps = _load("task_dependencies.json")
    if not isinstance(projects, list):
        projects = []
    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(deps, list):
        deps = []

    # Resolve project and task
    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if prj is None:
        _log("error", "NOT_FOUND", "Project not found.")
        return _err("NOT_FOUND", "Project not found.")
    task = next((t for t in tasks if isinstance(t, dict) and t.get("id") == task_id and t.get("project_id") == project_id), None)
    if task is None or task.get("deleted_at") is not None:
        _log("error", "NOT_FOUND", "Task not found.")
        return _err("NOT_FOUND", "Task not found.")

    # Enforce completed-task edit restrictions
    is_completed = (task.get("status") == "completed")
    if is_completed:
        forbidden = []
        for fld, val in [
            ("name", name), ("description", description), ("notes", notes), ("priority", priority),
            ("status", status), ("implementation_guide", implementation_guide),
            ("verification_criteria", verification_criteria), ("dependency_updates", dependency_updates),
            ("completion_report", completion_report), ("completed_at", completed_at),
        ]:
            if val is not None:
                forbidden.append(fld)
        if forbidden:
            _log("error", "INVALID_TRANSITION", "Completed tasks may only be updated for summary and related_files.", fields=forbidden)
            return _err("INVALID_TRANSITION", "Completed tasks may only be updated for summary and related_files.", fields=forbidden)

    # Status transition rules (lifecycle)
    transitions = {
        "planned": {"ready", "cancelled"},
        "ready": {"in_progress", "blocked", "cancelled"},
        "in_progress": {"blocked", "completed", "cancelled"},
        "blocked": {"ready", "in_progress", "cancelled"},
        "completed": set(),
        "cancelled": set(),
    }

    # Disallow setting completed via update_task (must use complete_task)
    if status == "completed" and task.get("status") != "completed":
        _log("error", "INVALID_TRANSITION", "Use complete_task to mark a task completed; update_task cannot set status='completed'.")
        return _err("INVALID_TRANSITION", "Use complete_task to mark a task completed; update_task cannot set status='completed'.")

    # Validate transition if status is changing (and not forbidden)
    if status is not None and status != task.get("status"):
        cur = task.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _log("error", "INVALID_TRANSITION", f"Invalid status transition from '{cur}' to '{status}'.")
            return _err("INVALID_TRANSITION", f"Invalid status transition from '{cur}' to '{status}'.")
        # completed_at invariant (completed_at is not null iff status='completed')
        if status != "completed" and completed_at is not None:
            _log("error", "VALIDATION_ERROR", "completed_at may only be set when status='completed'.")
            return _err("VALIDATION_ERROR", "completed_at may only be set when status='completed'.")

    # Prepare dependency changes
    dep_type_allowed = {"blocks", "requires_context", "optional"}
    to_set = to_add = to_remove = None
    if dependency_updates is not None:
        to_set = dependency_updates.get("set")
        to_add = dependency_updates.get("add")
        to_remove = dependency_updates.get("remove")
        for k in dependency_updates.keys():
            if k not in {"set", "add", "remove"}:
                _log("error", "VALIDATION_ERROR", "dependency_updates has invalid keys.")
                return _err("VALIDATION_ERROR", "dependency_updates has invalid keys.")
        if to_set is not None and not isinstance(to_set, list):
            _log("error", "VALIDATION_ERROR", "dependency_updates.set must be an array.")
            return _err("VALIDATION_ERROR", "dependency_updates.set must be an array.")
        if to_add is not None and not isinstance(to_add, list):
            _log("error", "VALIDATION_ERROR", "dependency_updates.add must be an array.")
            return _err("VALIDATION_ERROR", "dependency_updates.add must be an array.")
        if to_remove is not None:
            if not isinstance(to_remove, list) or any((not isinstance(x, str) or not re.match(r"^cot_tsk_[0-9A-Z]{18,}$", x)) for x in to_remove):
                _log("error", "VALIDATION_ERROR", "dependency_updates.remove must be an array of task IDs.")
                return _err("VALIDATION_ERROR", "dependency_updates.remove must be an array of task IDs.")

        def _validate_dep_item(it):
            if not isinstance(it, dict):
                return "Each dependency item must be an object."
            if set(it.keys()) != {"depends_on_task_id", "dependency_type"} and not (set(it.keys()) <= {"depends_on_task_id", "dependency_type"}):
                # tool schema says no additionalProperties, but enforce essentials
                pass
            dep_id = it.get("depends_on_task_id")
            dep_type = it.get("dependency_type")
            if not isinstance(dep_id, str) or not re.match(r"^cot_tsk_[0-9A-Z]{18,}$", dep_id):
                return "depends_on_task_id has invalid format."
            if dep_id == task_id:
                return "task_id cannot depend on itself."
            if not isinstance(dep_type, str) or dep_type not in dep_type_allowed:
                return "dependency_type is invalid."
            return None

        for arr in [to_set, to_add]:
            if arr is None:
                continue
            for it in arr:
                msg = _validate_dep_item(it)
                if msg:
                    _log("error", "VALIDATION_ERROR", msg)
                    return _err("VALIDATION_ERROR", msg)

    # Enforce name uniqueness among non-deleted tasks in project
    if name is not None and name != task.get("name"):
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("project_id") != project_id:
                continue
            if t.get("deleted_at") is not None:
                continue
            if t.get("id") != task_id and t.get("name") == name:
                _log("error", "CONFLICT", "Task name must be unique within a project (among non-deleted tasks).")
                return _err("CONFLICT", "Task name must be unique within a project (among non-deleted tasks).")

    # Helper: get existing tasks by id and ensure non-deleted + same project
    task_by_id = {t.get("id"): t for t in tasks if isinstance(t, dict) and t.get("project_id") == project_id and t.get("deleted_at") is None}
    if task_id not in task_by_id:
        _log("error", "NOT_FOUND", "Task not found.")
        return _err("NOT_FOUND", "Task not found.")

    # Apply core field updates (for non-completed tasks)
    mutated = False
    def _set_field(f, v):
        nonlocal mutated
        if v is not None and task.get(f) != v:
            task[f] = v
            mutated = True

    if not is_completed:
        _set_field("name", name.strip() if isinstance(name, str) else name)
        _set_field("description", description)
        _set_field("notes", notes)
        _set_field("priority", priority)
        _set_field("implementation_guide", implementation_guide)
        _set_field("verification_criteria", verification_criteria)
        if status is not None and status != task.get("status"):
            task["status"] = status
            # enforce completed_at invariant if moving away from completed (shouldn't happen due to lifecycle)
            mutated = True

    # Allowed even for completed tasks
    _set_field("summary", summary)
    if related_files is not None and task.get("related_files") != related_files:
        task["related_files"] = related_files
        mutated = True

    # completion_report/completed_at are typically set by complete_task; still validate invariants if provided
    if completion_report is not None:
        if task.get("status") != "completed":
            _log("error", "INVALID_TRANSITION", "completion_report may only be set when status='completed' (use complete_task).")
            return _err("INVALID_TRANSITION", "completion_report may only be set when status='completed' (use complete_task).")
        if task.get("completion_report") != completion_report:
            task["completion_report"] = completion_report
            mutated = True
    if completed_at is not None:
        if task.get("status") != "completed":
            _log("error", "INVALID_TRANSITION", "completed_at may only be set when status='completed' (use complete_task).")
            return _err("INVALID_TRANSITION", "completed_at may only be set when status='completed' (use complete_task).")
        parsed = _parse_dt_str(completed_at)
        if parsed is None:
            _log("error", "VALIDATION_ERROR", "completed_at must be an RFC3339 datetime string.")
            return _err("VALIDATION_ERROR", "completed_at must be an RFC3339 datetime string.")
        if task.get("completed_at") != parsed:
            task["completed_at"] = parsed
            mutated = True

    # Enforce completed_at invariant for existing completed tasks
    if task.get("status") == "completed" and task.get("completed_at") is None:
        _log("error", "CONFLICT", "Task status is 'completed' but completed_at is null (data invariant violated).")
        return _err("CONFLICT", "Task status is 'completed' but completed_at is null (data invariant violated).")
    if task.get("status") != "completed" and task.get("completed_at") is not None:
        _log("error", "CONFLICT", "Task completed_at must be null unless status='completed'.")
        return _err("CONFLICT", "Task completed_at must be null unless status='completed'.")

    # Dependency updates (only if not completed)
    dep_mutated = False
    if not is_completed and dependency_updates is not None:
        # Current outgoing deps for this task in this project
        cur_out = [d for d in deps if isinstance(d, dict) and d.get("project_id") == project_id and d.get("task_id") == task_id]
        cur_map = {(d.get("task_id"), d.get("depends_on_task_id")): d for d in cur_out if d.get("depends_on_task_id")}

        # Build desired set of edges (depends_on_task_id -> dependency_type)
        desired = {d.get("depends_on_task_id"): d.get("dependency_type") for d in cur_out if isinstance(d, dict)}
        if to_set is not None:
            desired = {}
            for it in to_set:
                desired[it["depends_on_task_id"]] = it["dependency_type"]
        if to_add is not None:
            for it in to_add:
                desired[it["depends_on_task_id"]] = it["dependency_type"]
        if to_remove is not None:
            for rid in to_remove:
                if rid in desired:
                    desired.pop(rid, None)

        # Enforce max 50 dependencies
        if len(desired) > 50:
            _log("error", "VALIDATION_ERROR", "A single task may have at most 50 dependencies.")
            return _err("VALIDATION_ERROR", "A single task may have at most 50 dependencies.")

        # FK integrity: referenced tasks must exist, non-deleted, same project
        for dep_task_id in desired.keys():
            ref = task_by_id.get(dep_task_id)
            if ref is None:
                _log("error", "NOT_FOUND", f"Dependency references missing or deleted task: {dep_task_id}.")
                return _err("NOT_FOUND", f"Dependency references missing or deleted task: {dep_task_id}.")
            if ref.get("project_id") != project_id:
                _log("error", "VALIDATION_ERROR", "Dependency tasks must belong to the same project.")
                return _err("VALIDATION_ERROR", "Dependency tasks must belong to the same project.")

        # Cycle detection: adding edges task_id -> dep_task_id must not create a cycle.
        # Build adjacency for project using desired outgoing for this task + existing for others.
        adj = {}
        for d in deps:
            if not isinstance(d, dict):
                continue
            if d.get("project_id") != project_id:
                continue
            a = d.get("task_id")
            b = d.get("depends_on_task_id")
            if not a or not b:
                continue
            if a == task_id:
                continue  # replaced by desired
            adj.setdefault(a, set()).add(b)
        adj[task_id] = set(desired.keys())

        # DFS to see if task_id is reachable from any of its deps (i.e., cycle exists)
        def _has_path(start, target):
            seen = set()
            stack = [start]
            while stack:
                x = stack.pop()
                if x == target:
                    return True
                if x in seen:
                    continue
                seen.add(x)
                for y in adj.get(x, ()):
                    if y not in seen:
                        stack.append(y)
            return False

        for dep_task_id in desired.keys():
            if _has_path(dep_task_id, task_id):
                _log("error", "CONFLICT", "Dependency update would create a cyclic dependency.")
                return _err("CONFLICT", "Dependency update would create a cyclic dependency.")

        # Apply changes: remove edges not in desired, upsert edges in desired
        desired_pairs = set((task_id, k) for k in desired.keys())
        new_deps = []
        removed = 0
        updated = 0
        created = 0
        now = _now()
        for d in deps:
            if not isinstance(d, dict):
                continue
            if d.get("project_id") == project_id and d.get("task_id") == task_id:
                pair = (task_id, d.get("depends_on_task_id"))
                if pair not in desired_pairs:
                    removed += 1
                    dep_mutated = True
                    continue
                # keep; may update type
                want_type = desired.get(d.get("depends_on_task_id"))
                if want_type and d.get("dependency_type") != want_type:
                    d["dependency_type"] = want_type
                    d["updated_at"] = now
                    updated += 1
                    dep_mutated = True
                new_deps.append(d)
            else:
                new_deps.append(d)

        existing_pairs = set((d.get("task_id"), d.get("depends_on_task_id")) for d in new_deps if isinstance(d, dict) and d.get("project_id") == project_id and d.get("task_id") == task_id)
        for dep_task_id, dep_type in desired.items():
            pair = (task_id, dep_task_id)
            if pair in existing_pairs:
                continue
            # unique(task_id, depends_on_task_id)
            row = {
                "id": _gen_id("cot_dep_"),
                "project_id": project_id,
                "task_id": task_id,
                "depends_on_task_id": dep_task_id,
                "dependency_type": dep_type,
                "created_at": now,
                "updated_at": now,
            }
            new_deps.append(row)
            created += 1
            dep_mutated = True

        if dep_mutated:
            deps = new_deps

    # Ensure there's at least one actual change
    if not mutated and not dep_mutated:
        _log("error", "NOT_FOUND", "No changes applied (request matched task but did not modify any fields).")
        return _err("NOT_FOUND", "No changes applied (request matched task but did not modify any fields).")

    # Persist
    task["updated_at"] = _now()
    _save("tasks.json", tasks)
    if dep_mutated:
        _save("task_dependencies.json", deps)

    # Return updated task (full row)
    _log("ok")
    return {
        "task": task,
        "dependency_updates_applied": bool(dep_mutated),
    }

def query_task(project_id, query=None, status=None, include_deleted=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, status_s, latency_ms, meta=None):
        fn = _ensure_request_log()
        logs = _load(fn)
        row = {
            "id": "cot_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _now(),
        }
        if meta:
            row["meta"] = meta
        logs.append(row)
        _save(fn, logs)

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or c.strip() == "":
            raise ValueError("cursor invalid")
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                raise ValueError("cursor offset invalid")
            return off
        except Exception:
            raise ValueError("cursor invalid")

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    t0 = time.time()
    endpoint = "query_task"

    try:
        if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "project_id"})
            return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")

        if query is not None and not isinstance(query, str):
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "query"})
            return _err("VALIDATION_ERROR", "query must be a string.", field="query")

        if status is not None:
            if not isinstance(status, list) or any(s not in {"planned", "ready", "in_progress", "blocked", "completed", "cancelled"} for s in status):
                _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "status"})
                return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")

        if include_deleted is not None and not isinstance(include_deleted, bool):
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "include_deleted"})
            return _err("VALIDATION_ERROR", "include_deleted must be boolean.", field="include_deleted")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")

        if sort_by is None:
            sort_by = "updated_at"
        if sort_by not in {"updated_at", "created_at", "priority", "status"}:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "sort_by"})
            return _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")

        if sort_order is None:
            sort_order = "desc"
        if sort_order not in {"asc", "desc"}:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "sort_order"})
            return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")

        try:
            offset = _decode_cursor(cursor)
        except Exception:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
    except Exception:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid input.")

    projects = _load("projects.json")
    if not any(p.get("id") == project_id for p in projects):
        _log(endpoint, "NOT_FOUND", (time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    tasks = _load("tasks.json")

    rows = [t for t in tasks if t.get("project_id") == project_id]
    if not include_deleted:
        rows = [t for t in rows if t.get("deleted_at") is None]

    if status is not None and len(status) > 0:
        st = set(status)
        rows = [t for t in rows if t.get("status") in st]

    # Query by exact ID or keyword
    if query is not None and query.strip() != "":
        q = query.strip()
        if re.match(r"^cot_tsk_[0-9A-Z]{18,}$", q):
            rows = [t for t in rows if t.get("id") == q]
        else:
            ql = q.lower()

            def _txt(x):
                return (x or "").lower() if isinstance(x, str) else ""

            rows = [
                t for t in rows
                if (ql in _txt(t.get("name"))
                    or ql in _txt(t.get("description"))
                    or ql in _txt(t.get("notes")))
            ]

    # Sort
    reverse = (sort_order == "desc")

    def _key(t):
        v = t.get(sort_by)
        if sort_by in {"updated_at", "created_at"}:
            # ISO strings sort lexicographically if consistent format; fallback to empty
            return v or ""
        if sort_by == "priority":
            return int(v) if isinstance(v, int) else 999999
        if sort_by == "status":
            return (v or "")
        return v or ""

    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    if offset > total:
        offset = total

    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    # Abbreviated task list
    def _abbr(t):
        return {
            "id": t.get("id"),
            "project_id": t.get("project_id"),
            "name": t.get("name"),
            "priority": t.get("priority"),
            "status": t.get("status"),
            "deleted_at": t.get("deleted_at"),
            "created_at": t.get("created_at"),
            "updated_at": t.get("updated_at"),
        }

    result = {
        "tasks": [_abbr(t) for t in page],
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
    }

    _log(endpoint, "OK", (time.time() - t0) * 1000, {"returned": len(page), "total": total, "has_more": has_more})

    return result

def get_task_detail(project_id, task_id, include_dependencies=None, include_deleted=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, latency_ms, project_id=None, task_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"cot_rql_{_gen_id()}",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "project_id": project_id,
            "task_id": task_id,
            "ts": _now()
        })
        _save("request_logs.json", logs)

    def _gen_id():
        import secrets, string
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return "".join(secrets.choice(alphabet) for _ in range(22))

    def _enforce_rate_limit(endpoint, project_id):
        # Simple global sliding window rate limit based on request_logs.json
        # 120 requests / 60 seconds per project per endpoint (if project_id provided), else global per endpoint.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_s = 60
        limit = 120
        cutoff = now - datetime.timedelta(seconds=window_s)

        def _parse_ts(s):
            try:
                if isinstance(s, str) and s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if project_id is not None and r.get("project_id") != project_id:
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts >= cutoff:
                count += 1
                if count >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=limit, window_seconds=window_s)
        return None

    t0 = time.time()

    try:
        if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
            latency = (time.time() - t0) * 1000
            _log("get_task_detail", "error", latency, project_id=project_id, task_id=task_id)
            return _err("VALIDATION_ERROR", "Malformed project_id.")
        if not isinstance(task_id, str) or not re.match(r"^cot_tsk_[0-9A-Z]{18,}$", task_id):
            latency = (time.time() - t0) * 1000
            _log("get_task_detail", "error", latency, project_id=project_id, task_id=task_id)
            return _err("VALIDATION_ERROR", "Malformed task_id.")
        if include_dependencies is not None and not isinstance(include_dependencies, bool):
            latency = (time.time() - t0) * 1000
            _log("get_task_detail", "error", latency, project_id=project_id, task_id=task_id)
            return _err("VALIDATION_ERROR", "include_dependencies must be a boolean.")
        if include_deleted is not None and not isinstance(include_deleted, bool):
            latency = (time.time() - t0) * 1000
            _log("get_task_detail", "error", latency, project_id=project_id, task_id=task_id)
            return _err("VALIDATION_ERROR", "include_deleted must be a boolean.")

        rl = _enforce_rate_limit("get_task_detail", project_id)
        if rl:
            latency = (time.time() - t0) * 1000
            _log("get_task_detail", "error", latency, project_id=project_id, task_id=task_id)
            return rl

        projects = _load("projects.json")
        if not any(isinstance(p, dict) and p.get("id") == project_id for p in projects):
            latency = (time.time() - t0) * 1000
            _log("get_task_detail", "error", latency, project_id=project_id, task_id=task_id)
            return _err("NOT_FOUND", "Project not found.", project_id=project_id)

        tasks = _load("tasks.json")
        task = None
        for r in tasks:
            if isinstance(r, dict) and r.get("id") == task_id and r.get("project_id") == project_id:
                task = r
                break
        if task is None:
            latency = (time.time() - t0) * 1000
            _log("get_task_detail", "error", latency, project_id=project_id, task_id=task_id)
            return _err("NOT_FOUND", "Task not found.", task_id=task_id)

        if task.get("deleted_at") is not None and not include_deleted:
            latency = (time.time() - t0) * 1000
            _log("get_task_detail", "error", latency, project_id=project_id, task_id=task_id)
            return _err("NOT_FOUND", "Task not found (deleted).", task_id=task_id)

        out = {"task": task}

        if include_dependencies:
            deps = _load("task_dependencies.json")
            outgoing = []
            incoming = []
            for d in deps:
                if not isinstance(d, dict):
                    continue
                if d.get("project_id") != project_id:
                    continue
                if d.get("task_id") == task_id:
                    outgoing.append(d)
                if d.get("depends_on_task_id") == task_id:
                    incoming.append(d)
            out["dependencies"] = {"outgoing": outgoing, "incoming": incoming}

        latency = (time.time() - t0) * 1000
        _log("get_task_detail", "ok", latency, project_id=project_id, task_id=task_id)
        return out
    except Exception as e:
        latency = (time.time() - t0) * 1000
        _log("get_task_detail", "error", latency, project_id=project_id, task_id=task_id)
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def process_thought(project_id, root_task_id, content, thought_session_id=None, next_thought_needed=None, mode=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "process_thought"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(22))

    def _log(status, code=None, message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("cot_rql_"),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "project_id": project_id if isinstance(project_id, str) else None,
            "root_task_id": root_task_id if isinstance(root_task_id, str) else None,
            "thought_session_id": thought_session_id if isinstance(thought_session_id, str) else None,
        }
        if code or message:
            row["error"] = {"code": code, "message": message}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Rate limit: 240/min per project per endpoint
    def _rate_limit_check():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if r.get("project_id") != project_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]) if ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        if cnt >= 240:
            return _err("RATE_LIMIT", "Rate limit exceeded for this endpoint (240/min).")
        return None

    # Validate inputs
    if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
        _log("error", "VALIDATION_ERROR", "Invalid project_id format.")
        return _err("VALIDATION_ERROR", "Invalid project_id format.")
    if not isinstance(root_task_id, str) or not re.match(r"^cot_tsk_[0-9A-Z]{18,}$", root_task_id):
        _log("error", "VALIDATION_ERROR", "Invalid root_task_id format.")
        return _err("VALIDATION_ERROR", "Invalid root_task_id format.")
    if thought_session_id is not None and (not isinstance(thought_session_id, str) or not re.match(r"^cot_ths_[0-9A-Z]{18,}$", thought_session_id)):
        _log("error", "VALIDATION_ERROR", "Invalid thought_session_id format.")
        return _err("VALIDATION_ERROR", "Invalid thought_session_id format.")
    if not isinstance(content, str) or content.strip() == "":
        _log("error", "VALIDATION_ERROR", "content must be a non-empty string.")
        return _err("VALIDATION_ERROR", "content must be a non-empty string.")
    if next_thought_needed is not None and not isinstance(next_thought_needed, bool):
        _log("error", "VALIDATION_ERROR", "next_thought_needed must be a boolean.")
        return _err("VALIDATION_ERROR", "next_thought_needed must be a boolean.")
    if mode is not None and mode != "process_thought":
        _log("error", "VALIDATION_ERROR", "mode must be 'process_thought' for this endpoint.")
        return _err("VALIDATION_ERROR", "mode must be 'process_thought' for this endpoint.")

    rl = _rate_limit_check()
    if rl:
        _log("error", rl["error"]["code"], rl["error"]["message"])
        return rl

    projects = _load("projects.json")
    tasks = _load("tasks.json")
    sessions = _load("thought_sessions.json")
    if not isinstance(projects, list):
        projects = []
    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(sessions, list):
        sessions = []

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if prj is None:
        _log("error", "NOT_FOUND", "Project not found.")
        return _err("NOT_FOUND", "Project not found.")

    root_task = next((t for t in tasks if isinstance(t, dict) and t.get("id") == root_task_id and t.get("project_id") == project_id and t.get("deleted_at") is None), None)
    if root_task is None:
        _log("error", "NOT_FOUND", "Root task not found.")
        return _err("NOT_FOUND", "Root task not found.")

    now = _now()

    # Find or create session
    sess = None
    if thought_session_id is not None:
        sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == thought_session_id), None)
        if sess is None:
            _log("error", "NOT_FOUND", "thought_session_id not found.")
            return _err("NOT_FOUND", "thought_session_id not found.")
        if sess.get("project_id") != project_id:
            _log("error", "CONFLICT", "thought_session_id does not belong to the provided project_id.")
            return _err("CONFLICT", "thought_session_id does not belong to the provided project_id.")
        if sess.get("root_task_id") is not None and sess.get("root_task_id") != root_task_id:
            _log("error", "CONFLICT", "thought_session_id is for a different root_task_id.")
            return _err("CONFLICT", "thought_session_id is for a different root_task_id.")
        if sess.get("status") != "open":
            _log("error", "INVALID_TRANSITION", "Cannot append to a thought session that is not open.")
            return _err("INVALID_TRANSITION", "Cannot append to a thought session that is not open.")
        if sess.get("mode") != "process_thought":
            _log("error", "CONFLICT", "thought_session_id mode mismatch; expected 'process_thought'.")
            return _err("CONFLICT", "thought_session_id mode mismatch; expected 'process_thought'.")
    else:
        sess = {
            "id": _gen_id("cot_ths_"),
            "project_id": project_id,
            "root_task_id": root_task_id,
            "mode": "process_thought",
            "status": "open",
            "summary": None,
            "next_thought_needed": True if next_thought_needed is None else bool(next_thought_needed),
            "created_at": now,
            "updated_at": now,
            "closed_at": None,
        }
        sessions.append(sess)

    # Update session with this "step" (high-level artifact only)
    # Store a compact summary that reflects latest content without persisting chain-of-thought details.
    # (We keep only high-level metadata; do not store full content verbatim.)
    truncated = content.strip()
    if len(truncated) > 240:
        truncated = truncated[:240] + "…"
    sess["summary"] = f"Processed thought step at {now}. Input preview: {truncated}"
    if next_thought_needed is not None:
        sess["next_thought_needed"] = bool(next_thought_needed)

    # Close session automatically when next_thought_needed is false
    if sess.get("next_thought_needed") is False and sess.get("status") == "open":
        sess["status"] = "closed"
        sess["closed_at"] = now

    sess["updated_at"] = now

    _save("thought_sessions.json", sessions)
    _log("ok", meta={"created_new_session": thought_session_id is None, "session_status": sess.get("status")})

    return {
        "thought_session": sess,
        "next_thought_needed": sess.get("next_thought_needed"),
    }

def init_project_rules(project_id, rules_spec, rules_version=None, summary=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(22))

    def _log(endpoint, status, latency_ms, project_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"cot_rql_{_gen_id('')}",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "project_id": project_id,
            "ts": _now()
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit(endpoint, project_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_s = 60
        limit = 60  # lower for admin-ish mutation
        cutoff = now - datetime.timedelta(seconds=window_s)

        def _parse_ts(s):
            try:
                if isinstance(s, str) and s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            if project_id is not None and r.get("project_id") != project_id:
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts >= cutoff:
                count += 1
                if count >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=limit, window_seconds=window_s)
        return None

    t0 = time.time()

    try:
        if not isinstance(project_id, str) or not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
            latency = (time.time() - t0) * 1000
            _log("init_project_rules", "error", latency, project_id=project_id)
            return _err("VALIDATION_ERROR", "Malformed project_id.")
        if not isinstance(rules_spec, dict):
            latency = (time.time() - t0) * 1000
            _log("init_project_rules", "error", latency, project_id=project_id)
            return _err("VALIDATION_ERROR", "rules_spec must be an object.")
        if rules_version is not None and not isinstance(rules_version, int):
            latency = (time.time() - t0) * 1000
            _log("init_project_rules", "error", latency, project_id=project_id)
            return _err("VALIDATION_ERROR", "rules_version must be an integer when provided.")
        if rules_version is not None and rules_version < 0:
            latency = (time.time() - t0) * 1000
            _log("init_project_rules", "error", latency, project_id=project_id)
            return _err("VALIDATION_ERROR", "rules_version must be >= 0.")
        if summary is not None and not isinstance(summary, str):
            latency = (time.time() - t0) * 1000
            _log("init_project_rules", "error", latency, project_id=project_id)
            return _err("VALIDATION_ERROR", "summary must be a string when provided.")

        rl = _enforce_rate_limit("init_project_rules", project_id)
        if rl:
            latency = (time.time() - t0) * 1000
            _log("init_project_rules", "error", latency, project_id=project_id)
            return rl

        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []

        proj = None
        for p in projects:
            if isinstance(p, dict) and p.get("id") == project_id:
                proj = p
                break
        if proj is None:
            latency = (time.time() - t0) * 1000
            _log("init_project_rules", "error", latency, project_id=project_id)
            return _err("NOT_FOUND", "Project not found.", project_id=project_id)

        current_version = proj.get("rules_version")
        if not isinstance(current_version, int):
            current_version = 0

        # Business rule: increment rules_version by 1 on each upsert.
        # If caller provides rules_version, treat it as optimistic concurrency expectation of current version
        # (must match current); then we still increment by 1 on write.
        if rules_version is not None and rules_version != current_version:
            latency = (time.time() - t0) * 1000
            _log("init_project_rules", "error", latency, project_id=project_id)
            return _err("CONFLICT", "rules_version conflict.", expected=current_version, provided=rules_version)

        proj["rules_spec"] = rules_spec
        proj["rules_version"] = int(current_version) + 1
        proj["rules_updated_at"] = _now()
        proj["updated_at"] = _now()
        if proj.get("created_at") is None:
            proj["created_at"] = _now()
        if proj.get("status") not in ("active", "archived"):
            proj["status"] = "active"
        if proj.get("name") is None or not isinstance(proj.get("name"), str) or proj.get("name").strip() == "":
            proj["name"] = proj.get("name") if isinstance(proj.get("name"), str) and proj.get("name").strip() else f"Project {project_id}"

        _save("projects.json", projects)

        # Create thought session row with mode='init_project_rules'
        sessions = _load("thought_sessions.json")
        if not isinstance(sessions, list):
            sessions = []
        ths = {
            "id": _gen_id("cot_ths_"),
            "project_id": project_id,
            "root_task_id": None,
            "mode": "init_project_rules",
            "status": "closed",
            "summary": summary if isinstance(summary, str) and summary.strip() != "" else "Initialized/updated project rules/spec.",
            "next_thought_needed": False,
            "created_at": _now(),
            "updated_at": _now(),
            "closed_at": _now()
        }
        sessions.append(ths)
        _save("thought_sessions.json", sessions)

        latency = (time.time() - t0) * 1000
        _log("init_project_rules", "ok", latency, project_id=project_id)
        return {
            "project": {
                "id": proj.get("id"),
                "rules_version": proj.get("rules_version"),
                "rules_updated_at": proj.get("rules_updated_at"),
                "updated_at": proj.get("updated_at")
            },
            "thought_session": ths
        }
    except Exception as e:
        latency = (time.time() - t0) * 1000
        _log("init_project_rules", "error", latency, project_id=project_id)
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def list_projects(repository_url=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id():
        import secrets
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return "".join(secrets.choice(alphabet) for _ in range(22))

    def _log(endpoint, status, latency_ms):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"cot_rql_{_gen_id()}",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "ts": _now()
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit(endpoint):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = datetime.datetime.utcnow()
        window_s = 60
        limit = 240
        cutoff = now - datetime.timedelta(seconds=window_s)

        def _parse_ts(s):
            try:
                if isinstance(s, str) and s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None

        count = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_ts(r.get("ts"))
            if ts is None:
                continue
            if ts >= cutoff:
                count += 1
                if count >= limit:
                    return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=limit, window_seconds=window_s)
        return None

    def _parse_cursor(c):
        # Opaque cursor format: "u:<updated_at>|i:<id>"
        if c is None:
            return None
        if not isinstance(c, str) or c.strip() == "":
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        try:
            parts = c.split("|")
            kv = {}
            for p in parts:
                k, v = p.split(":", 1)
                kv[k] = v
            if "u" not in kv or "i" not in kv:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            return {"updated_at": kv["u"], "id": kv["i"]}
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    t0 = time.time()

    try:
        if repository_url is not None and not isinstance(repository_url, str):
            latency = (time.time() - t0) * 1000
            _log("list_projects", "error", latency)
            return _err("VALIDATION_ERROR", "repository_url must be a string.")
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "archived"):
                latency = (time.time() - t0) * 1000
                _log("list_projects", "error", latency)
                return _err("VALIDATION_ERROR", "status must be one of: active, archived.")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            latency = (time.time() - t0) * 1000
            _log("list_projects", "error", latency)
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        cur = _parse_cursor(cursor)
        if isinstance(cur, dict) and "error" in cur:
            latency = (time.time() - t0) * 1000
            _log("list_projects", "error", latency)
            return cur

        rl = _enforce_rate_limit("list_projects")
        if rl:
            latency = (time.time() - t0) * 1000
            _log("list_projects", "error", latency)
            return rl

        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []

        rows = []
        for p in projects:
            if not isinstance(p, dict):
                continue
            if repository_url is not None and p.get("repository_url") != repository_url:
                continue
            if status is not None and p.get("status") != status:
                continue
            rows.append(p)

        # Sort by updated_at desc, then id desc
        def _key(p):
            return (p.get("updated_at") or "", p.get("id") or "")

        rows.sort(key=_key, reverse=True)

        # Apply cursor: return items strictly older than cursor position
        if cur is not None:
            cu = cur["updated_at"]
            cid = cur["id"]

            def _after_cursor(p):
                u = p.get("updated_at") or ""
                i = p.get("id") or ""
                # sorted desc; we want those with (u,i) < (cu,cid)
                return (u, i) < (cu, cid)

            rows = [p for p in rows if _after_cursor(p)]

        total = len(rows)
        page = rows[:limit]
        has_more = total > len(page)
        next_cursor = None
        if has_more and len(page) > 0:
            last = page[-1]
            next_cursor = f"u:{last.get('updated_at') or ''}|i:{last.get('id') or ''}"

        latency = (time.time() - t0) * 1000
        _log("list_projects", "ok", latency)
        return {
            "projects": page,
            "meta": {
                "limit": limit,
                "total": total,
                "has_more": has_more,
                "next_cursor": next_cursor
            }
        }
    except Exception as e:
        latency = (time.time() - t0) * 1000
        _log("list_projects", "error", latency)
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def get_project(project_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Observability: request log (best-effort; tool must not fail if log collection absent)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    log_row = {
        "id": "cot_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
        "endpoint": "get_project",
        "timestamp": now,
        "status": "error",
        "latency_ms": None,
        "project_id": project_id,
        "credential_id": None
    }

    # Validate
    if not isinstance(project_id, str):
        log_row["status"] = "error"
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "project_id must be a string", field="project_id")

    if not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
        log_row["status"] = "error"
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row)
        _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "project_id does not match required pattern", field="project_id")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    prj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            prj = p
            break

    if prj is None:
        log_row["status"] = "error"
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
