            logs.append(log_row); _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "status must be a string", field="status")
        if status not in ("active", "archived"):
            log_row["latency_ms"] = int((time.time() - t0) * 1000)
            logs.append(log_row); _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "status must be one of: active, archived", field="status")

    if name is None and repository_url is None and status is None:
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "No mutable fields provided to update")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    idx = None
    for i, p in enumerate(projects):
        if isinstance(p, dict) and p.get("id") == project_id:
            idx = i
            break
    if idx is None:
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Project not found", project_id=project_id)

    prj = projects[idx]
    if not isinstance(prj, dict):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Project not found", project_id=project_id)

    # Unique(repository_url) where not null
    if repository_url is not None:
        for p in projects:
            if not isinstance(p, dict):
                continue
            if p.get("id") != project_id and p.get("repository_url") is not None and p.get("repository_url") == repository_url:
                log_row["latency_ms"] = int((time.time() - t0) * 1000)
                logs.append(log_row); _save("request_logs.json", logs)
                return _err("CONFLICT", "repository_url must be unique among projects", field="repository_url")

    # Lifecycle transition validation
    if status is not None:
        cur = prj.get("status")
        if cur not in ("active", "archived"):
            # corrupted state; treat as invalid transition
            log_row["latency_ms"] = int((time.time() - t0) * 1000)
            logs.append(log_row); _save("request_logs.json", logs)
            return _err("INVALID_TRANSITION", "Current project status is invalid", current_status=cur)
        if status != cur:
            allowed = {"active": ["archived"], "archived": ["active"]}.get(cur, [])
            if status not in allowed:
                log_row["latency_ms"] = int((time.time() - t0) * 1000)
                logs.append(log_row); _save("request_logs.json", logs)
                return _err("INVALID_TRANSITION", "Invalid project status transition", from_status=cur, to_status=status)

    # Apply changes
    changed = False
    if name is not None and name != prj.get("name"):
        prj["name"] = name
        changed = True
    if repository_url is not None and repository_url != prj.get("repository_url"):
        prj["repository_url"] = repository_url
        changed = True
    if status is not None and status != prj.get("status"):
        prj["status"] = status
        changed = True

    if not changed:
        # Idempotent update: still update updated_at? Realistic services often do not; we won't mutate.
        log_row["status"] = "ok"
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return {"project": prj}

    prj["updated_at"] = now
    projects[idx] = prj
    _save("projects.json", projects)

    log_row["status"] = "ok"
    log_row["latency_ms"] = int((time.time() - t0) * 1000)
    logs.append(log_row)
    _save("request_logs.json", logs)

    return {"project": prj}

def create_task(project_id, name, description=None, notes=None, priority=None, status=None, implementation_guide=None, verification_criteria=None, related_files=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0373000" if __import__("os").path.isdir("./environment_mix/0373000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    log_row = {
        "id": "cot_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
        "endpoint": "create_task",
        "timestamp": now,
        "status": "error",
        "latency_ms": None,
        "project_id": project_id,
        "credential_id": None
    }

    # Validate basics
    if not isinstance(project_id, str):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "project_id must be a string", field="project_id")
    if not re.match(r"^cot_prj_[0-9A-Z]{18,}$", project_id):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "project_id does not match required pattern", field="project_id")

    if not isinstance(name, str):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "name must be a string", field="name")
    if name.strip() == "":
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "name must not be empty", field="name")

    if description is not None and not isinstance(description, str):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "description must be a string", field="description")
    if notes is not None and not isinstance(notes, str):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "notes must be a string", field="notes")
    if implementation_guide is not None and not isinstance(implementation_guide, str):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "implementation_guide must be a string", field="implementation_guide")
    if verification_criteria is not None and not isinstance(verification_criteria, str):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "verification_criteria must be a string", field="verification_criteria")

    if priority is None:
        priority = 3
    if not isinstance(priority, int):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "priority must be an integer", field="priority")
    # Schema constraint: between 1 and 5
    if priority < 1 or priority > 5:
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "priority must be between 1 and 5", field="priority")

    if status is None:
        status = "planned"
    if not isinstance(status, str):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "status must be a string", field="status")
    if status not in ("planned", "ready"):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "status must be one of: planned, ready", field="status")

    if related_files is None:
        related_files = []
    if not isinstance(related_files, list):
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "related_files must be an array of strings", field="related_files")
    if len(related_files) > 200:
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("VALIDATION_ERROR", "related_files length must be <= 200", field="related_files")
    for i, rf in enumerate(related_files):
        if not isinstance(rf, str):
            log_row["latency_ms"] = int((time.time() - t0) * 1000)
            logs.append(log_row); _save("request_logs.json", logs)
            return _err("VALIDATION_ERROR", "related_files items must be strings", field="related_files", index=i)

    # Check project exists
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    prj = None
    for p in projects:
        if isinstance(p, dict) and p.get("id") == project_id:
            prj = p
            break
    if prj is None:
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("NOT_FOUND", "Project not found", project_id=project_id)

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    # Enforce per-project non-deleted tasks limit (<= 500)
    active_count = 0
    for t in tasks:
        if isinstance(t, dict) and t.get("project_id") == project_id and t.get("deleted_at") is None:
            active_count += 1
    if active_count >= 500:
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("QUOTA_EXCEEDED", "Project task limit exceeded (max 500 non-deleted tasks)", limit=500)

    # Unique(project_id, name) where deleted_at is null
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("project_id") == project_id and t.get("deleted_at") is None and t.get("name") == name:
            log_row["latency_ms"] = int((time.time() - t0) * 1000)
            logs.append(log_row); _save("request_logs.json", logs)
            return _err("CONFLICT", "An active task with this name already exists in the project", field="name")

    # Generate id
    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    def _new_id(prefix):
        raw = int(datetime.datetime.utcnow().strftime("%y%m%d%H%M%S%f"))
        s = ""
        n = raw
        for _ in range(18):
            n, r = divmod(n, 36)
            s = alphabet[r] + s
        return prefix + s

    existing_ids = {t.get("id") for t in tasks if isinstance(t, dict)}
    task_id = _new_id("cot_tsk_")
    # ensure uniqueness
    tries = 0
    while task_id in existing_ids and tries < 10:
        time.sleep(0.001)
        task_id = _new_id("cot_tsk_")
        tries += 1
    if task_id in existing_ids:
        log_row["latency_ms"] = int((time.time() - t0) * 1000)
        logs.append(log_row); _save("request_logs.json", logs)
        return _err("CONFLICT", "Could not allocate unique task id")

    row = {
        "id": task_id,
        "project_id": project_id,
        "name": name,
        "description": description,
        "notes": notes,
        "priority": priority,
        "status": status,
        "implementation_guide": implementation_guide,
        "verification_criteria": verification_criteria,
        "related_files": related_files,
        "summary": None,
        "completion_report": None,
        "completed_at": None,
        "deleted_at": None,
        "created_at": now,
        "updated_at": now
    }

    # Constraints: completed_at is not null iff status='completed' (we only allow planned/ready)
    # so completed_at must be null; already set.

    tasks.append(row)
    _save("tasks.json", tasks)

    log_row["status"] = "ok"
    log_row["latency_ms"] = int((time.time() - t0) * 1000)
    logs.append(log_row)
    _save("request_logs.json", logs)

    return {"task": row}
